// All art is original SVG, generated by scripts/draw-art.mjs into public/art/.
// The stable name / size contract is shared by every screen and the game data.
import { createContext, useContext } from "react";
export const Expression = createContext("normal");
const LABELS = {
  mugi: "ムギ（くま）",
  chikuta: "チクタ（りす）",
  ruru: "ルル（うさぎ）",
  memo: "メモ（ねこ）",
  player: "きみ",
  maruta: "まるた",
  ishi: "いし",
  keito: "けいと",
  hana: "はな",
  hirameki: "ひらめきの み",
  sakana: "さかな",
  kago: "かご",
  monosashi: "ものさし",
  compass: "コンパス",
  mushimegane: "むしめがね",
  isu: "まるたの いす",
  takibi: "たきび",
  tent: "テント",
  kadan: "はなだん",
  furin: "ふうりん",
  tako: "たこ",
  lantern: "ランタン",
  telescope: "ぼうえんきょう",
  sofa: "ふかふか ソファ",
  koya: "きの こや",
  forest: "もり",
  fishing: "つり",
  workshop: "つくる",
  camp: "キャンプ",
  map: "たからのちず",
  chest: "たからばこ",
  bag: "もちもの",
  settings: "せってい",
  speaker: "よみあげ",
  soundOff: "おと なし",
  heart: "なかよし",
  heartEmpty: "",
  star: "とくべつ",
  sparkle: "",
  party: "おめでとう",
  moon: "よる",
  sun: "ひる",
  wave: "いけ",
  bobber: "うき",
  away: "おでかけ中",
  lock: "まだ つくれない",
  back: "もどる",
};
export const ART = Object.fromEntries(
  Object.entries(LABELS).map(([name, label]) => [name, { label }]),
);
const CHARACTERS = new Set(["mugi", "chikuta", "ruru", "memo", "player"]);
export default function Art({
  name,
  size = "md",
  className = "",
  title,
  variant,
}) {
  const expression = useContext(Expression);
  const label = title ?? ART[name]?.label ?? name;
  const character = CHARACTERS.has(name);
  const mood = variant || expression;
  const file = ART[name]
    ? name +
      (character && ["happy", "worried"].includes(mood) ? `-${mood}` : "")
    : "sparkle";
  return (
    <span
      className={`art art-${size} art-${name} ${character ? "art-character" : ""} ${className}`.trim()}
      role={label ? "img" : undefined}
      aria-label={label || undefined}
      aria-hidden={label ? undefined : true}
    >
      <img
        src={`${import.meta.env.BASE_URL}art/${file}.svg`}
        alt=""
        draggable="false"
        width="120"
        height="120"
      />
    </span>
  );
}
